<template>
  <main class="hh-page referral-detail"><router-link to="/referencias" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a referencias</router-link><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span><p class="text-muted mt-2">Consultando referencia…</p></div><div v-else-if="error&&!reference" class="alert alert-danger">{{error}}</div><template v-else-if="reference">
    <section class="detail-hero"><div class="ref-icon"><i class="ph ph-arrows-left-right"></i></div><div><span>REFERENCIA ASISTENCIAL</span><h1>{{reference.numero_referencia||`Referencia #${reference.id}`}}</h1><p>{{patientName}} · {{reference.paciente?.identificacion||'Identificación no informada'}}</p></div><div class="hero-status"><small>ESTADO ACTUAL</small><strong :style="{'--status':reference.estado?.color||'#fff'}"><i class="ph ph-circle-fill"></i>{{reference.estado?.nombre||reference.estado?.codigo}}</strong></div></section>
    <div v-if="notice.text" class="alert mt-3" :class="`alert-${notice.type}`">{{notice.text}}</div>
    <div class="action-strip mt-3"><div><span><small>Origen</small><strong>{{reference.establecimiento_origen?.nombre||'No informado'}}</strong></span><span><small>Prioridad</small><strong>{{reference.prioridad?.nombre||'No informada'}}</strong></span><span><small>Tipo</small><strong>{{reference.tipo_referencia?.nombre||'No informado'}}</strong></span></div><div class="d-flex gap-2"><router-link v-if="canCounterReference||reference.contrareferencia" :to="`/referencias/${reference.id}/contrareferencia`" class="btn btn-outline-primary"><i class="ph ph-arrow-bend-up-left me-1"></i>{{reference.contrareferencia?'Ver contrarreferencia':'Crear contrarreferencia'}}</router-link><button v-if="allowedStates.length" class="btn btn-primary" @click="stateModal=true"><i class="ph ph-arrows-clockwise me-1"></i>Cambiar estado</button></div></div>
    <div class="detail-shell mt-4"><nav><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="openTab(item.id)"><i :class="item.icon"></i>{{item.label}}<span v-if="item.id==='documents'">{{documents.length}}</span></button></nav><section class="tab-panel">
      <template v-if="tab==='summary'"><div class="summary-grid"><article v-for="item in summary" :key="item.label"><i :class="item.icon"></i><span><small>{{item.label}}</small><strong>{{item.value}}</strong></span></article></div></template>
      <template v-else-if="tab==='clinical'"><div class="clinical-grid"><article v-for="item in clinicalItems" :key="item.label"><small>{{item.label}}</small><p>{{item.value||'No registrado'}}</p></article></div></template>
      <template v-else-if="tab==='packages'"><div v-if="!packages.length" class="empty"><i class="ph ph-package"></i><p>No hay paquetes solicitados.</p></div><div v-else class="records"><article v-for="item in packages" :key="item.id"><span><i class="ph ph-package"></i></span><div><strong>{{item.paquete?.nombre||`Paquete #${item.id}`}}</strong><small>{{item.paquete?.codigo}} · Cantidad {{item.cantidad}}</small><p>{{item.observaciones}}</p></div></article></div></template>
      <template v-else-if="tab==='documents'"><div class="upload-box"><input ref="fileInput" type="file" class="form-control" accept=".pdf,image/*" @change="selectedFile=$event.target.files[0]"><button class="btn btn-primary" :disabled="!selectedFile||uploading" @click="uploadDocument"><span v-if="uploading" class="spinner-border spinner-border-sm me-1"></span>Adjuntar</button><small>Archivo máximo: 10 MB. El tipo y origen deben existir en los catálogos.</small></div><div v-if="!documents.length" class="empty"><i class="ph ph-file-dashed"></i><p>No hay documentos adjuntos.</p></div><div v-else class="records"><article v-for="item in documents" :key="item.id"><span><i class="ph ph-file"></i></span><div><strong>{{item.nombre_archivo||item.nombre||`Documento #${item.id}`}}</strong><small>{{item.tipo_documento?.nombre||item.descripcion}}</small></div></article></div></template>
      <template v-else-if="tab==='history'"><div v-if="tabLoading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><div v-else-if="!history.length" class="empty"><i class="ph ph-clock-counter-clockwise"></i><p>No hay cambios registrados.</p></div><div v-else class="timeline"><article v-for="item in history" :key="item.id"><span></span><div><small>{{formatDateTime(item.created_at||item.fecha)}}</small><strong>{{item.estado_anterior?.nombre||'Inicio'}} → {{item.estado_nuevo?.nombre||item.estado?.nombre}}</strong><p>{{item.observaciones||item.comentario}} <em>{{item.usuario?.name||item.usuario}}</em></p></div></article></div></template>
    </section></div>
    <Teleport to="body"><div v-if="stateModal" class="modal-layer" @mousedown.self="closeStateModal"><section class="state-modal"><header><div><small>GESTIÓN DE ESTADO</small><h3>Actualizar referencia</h3></div><button class="btn-close" :disabled="saving" @click="closeStateModal"></button></header><form @submit.prevent="changeState"><div class="modal-body"><div v-if="modalError" class="alert alert-danger">{{modalError}}</div><label class="form-label">Nuevo estado *</label><select v-model="stateForm.stateId" class="form-select" required><option value="" disabled>Seleccione una transición permitida</option><option v-for="item in allowedStates" :key="stateId(item)" :value="stateId(item)">{{item.nombre||item.codigo}}</option></select><label class="form-label mt-3">Comentario</label><textarea v-model.trim="stateForm.comment" class="form-control" rows="2"></textarea><label v-if="Number(stateForm.stateId)===7" class="form-label mt-3">Motivo de cancelación *</label><textarea v-if="Number(stateForm.stateId)===7" v-model.trim="stateForm.cancelReason" class="form-control" rows="2" required></textarea><label v-if="Number(stateForm.stateId)===8" class="form-label mt-3">Motivo de rechazo *</label><textarea v-if="Number(stateForm.stateId)===8" v-model.trim="stateForm.rejectReason" class="form-control" rows="2" required></textarea><div v-if="Number(stateForm.stateId)===3" class="vitals"><h4><i class="ph ph-heartbeat me-1"></i>Signos vitales de recepción</h4><div class="row g-2"><div v-for="field in vitalFields" :key="field.key" class="col-6 col-md-4"><label class="form-label">{{field.label}} *</label><input v-model.number="stateForm.vitals[field.key]" type="number" :min="field.min" :max="field.max" :step="field.step||1" class="form-control" required></div></div></div></div><footer><button type="button" class="btn btn-outline-secondary" :disabled="saving" @click="closeStateModal">Cancelar</button><button class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Confirmar cambio</button></footer></form></section></div></Teleport>
  </template></main>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{adjuntarDocumentoReferencia,cambiarEstadoReferencia,consultarEstadosPermitidos,consultarHistorialReferencia,consultarReferencia,listarDocumentosReferencia,listarPaquetesReferencia,consultarCatalogosReferencia}from'@/services/referencias';const route=useRoute(),reference=ref(null),loading=ref(true),error=ref(''),notice=reactive({text:'',type:'success'}),tab=ref('summary'),tabLoading=ref(false),history=ref([]),packages=ref([]),documents=ref([]),allowedStates=ref([]),stateModal=ref(false),saving=ref(false),modalError=ref(''),selectedFile=ref(null),uploading=ref(false),fileInput=ref(null),documentTypes=ref([]),documentOrigins=ref([]);const stateForm=reactive({stateId:'',comment:'',cancelReason:'',rejectReason:'',vitals:{presion_arterial_sistolica:'',presion_arterial_diastolica:'',frecuencia_cardiaca:'',frecuencia_respiratoria:'',temperatura:'',saturacion_oxigeno:'',peso:'',talla:''}});const tabs=[{id:'summary',label:'Resumen',icon:'ph ph-squares-four'},{id:'clinical',label:'Información clínica',icon:'ph ph-heartbeat'},{id:'packages',label:'Paquetes',icon:'ph ph-package'},{id:'documents',label:'Documentos',icon:'ph ph-files'},{id:'history',label:'Historial',icon:'ph ph-clock-counter-clockwise'}],vitalFields=[{key:'presion_arterial_sistolica',label:'Sistólica',min:0,max:300},{key:'presion_arterial_diastolica',label:'Diastólica',min:0,max:200},{key:'frecuencia_cardiaca',label:'F. cardiaca',min:0,max:300},{key:'frecuencia_respiratoria',label:'F. respiratoria',min:0,max:100},{key:'temperatura',label:'Temperatura',min:30,max:45,step:.1},{key:'saturacion_oxigeno',label:'Saturación',min:0,max:100},{key:'peso',label:'Peso',min:0,max:500,step:.1},{key:'talla',label:'Talla',min:0,max:300}];const array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],stateId=x=>x.id??x.estado_id,patientName=computed(()=>reference.value?.paciente?.nombre||reference.value?.paciente?.nombre_completo||'Paciente'),canCounterReference=computed(()=>Number(reference.value?.estado?.id||reference.value?.estado_id)===5&&!reference.value?.contrareferencia),formatDateTime=v=>v?new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'Sin fecha';const summary=computed(()=>[{label:'Paciente',value:patientName.value,icon:'ph ph-user'},{label:'Institución de origen',value:reference.value.establecimiento_origen?.nombre||'No informada',icon:'ph ph-buildings'},{label:'Médico que refiere',value:reference.value.medico_refiere_nombre||'No informado',icon:'ph ph-stethoscope'},{label:'Médico receptor',value:reference.value.medico_receptor?.name||'Por asignar',icon:'ph ph-user-focus'},{label:'Transporte',value:reference.value.medio_transporte?.nombre||'No informado',icon:'ph ph-ambulance'},{label:'Traslado programado',value:formatDateTime(reference.value.fecha_traslado_programada),icon:'ph ph-calendar'}]),clinicalItems=computed(()=>{const d=reference.value.detalle_clinico||{};return[{label:'Motivo de consulta',value:d.motivo_consulta},{label:'Enfermedad actual',value:d.enfermedad_actual},{label:'Diagnóstico principal',value:d.diagnostico_principal?.nombre||d.diagnostico_principal_cie10},{label:'Antecedentes',value:d.antecedentes_relevantes},{label:'Alergias',value:d.alergias},{label:'Tratamiento actual',value:d.tratamiento_actual},{label:'Exámenes realizados',value:d.examenes_realizados},{label:'Observaciones clínicas',value:d.observaciones_clinicas}]});async function load(){loading.value=true;error.value='';try{const r=await consultarReferencia(route.params.id);reference.value=r?.data||r;const s=await consultarEstadosPermitidos(reference.value.estado?.id||reference.value.estado_id);allowedStates.value=array(s)}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}async function openTab(id){tab.value=id;tabLoading.value=true;try{if(id==='history')history.value=array(await consultarHistorialReferencia(route.params.id));if(id==='packages')packages.value=array(await listarPaquetesReferencia(route.params.id));if(id==='documents')documents.value=array(await listarDocumentosReferencia(route.params.id))}catch(e){notice.type='danger';notice.text=obtenerMensajeError(e)}finally{tabLoading.value=false}}function closeStateModal(){if(!saving.value){stateModal.value=false;stateForm.stateId='';modalError.value=''}}async function changeState(){saving.value=true;modalError.value='';try{const payload={estado_codigo:Number(stateForm.stateId),comentario:stateForm.comment};if(Number(stateForm.stateId)===7)payload.motivo_cancelacion=stateForm.cancelReason;if(Number(stateForm.stateId)===8)payload.motivo_rechazo=stateForm.rejectReason;if(Number(stateForm.stateId)===3)payload.signos_vitales=Object.fromEntries(Object.entries(stateForm.vitals).filter(([,v])=>v!==''));await cambiarEstadoReferencia(route.params.id,payload);closeStateModal();notice.type='success';notice.text='Estado actualizado correctamente.';await load()}catch(e){modalError.value=obtenerMensajeError(e);if(e.status===403)await load()}finally{saving.value=false}}async function uploadDocument(){if(!selectedFile.value)return;if(selectedFile.value.size>10*1024*1024){notice.type='danger';notice.text='El archivo supera el máximo de 10 MB.';return}const type=documentTypes.value[0],origin=documentOrigins.value.find(x=>String(x.codigo||x.nombre).toUpperCase().includes('REFERENCIA'))||documentOrigins.value[0];if(!type||!origin){notice.type='warning';notice.text='No hay tipo u origen documental disponible en los catálogos.';return}uploading.value=true;try{const data=new FormData();data.append('archivo',selectedFile.value);data.append('tipo_documento_id',stateId(type));data.append('origen_id',stateId(origin));await adjuntarDocumentoReferencia(route.params.id,data);selectedFile.value=null;if(fileInput.value)fileInput.value.value='';await openTab('documents')}catch(e){notice.type='danger';notice.text=obtenerMensajeError(e)}finally{uploading.value=false}}onMounted(async()=>{const catalog=await consultarCatalogosReferencia().catch(()=>null);const source=catalog?.data||catalog||{};documentTypes.value=source.tipos_documento||source.tipos_documentos||[];documentOrigins.value=source.origenes_documento||source.origenes_documentos||[];await load()})
</script>
