state-modal header small{color:var(--bs-primary);font-size:.58rem;font-weight:800}.state-modal h3{margin:.1rem 0;font-size:1.05rem}.state-modal .modal-body{padding:1.2rem}.state-modal footer{display:flex;justify-content:flex-end;gap:.6rem;padding:1rem 1.2rem;border-top:1px solid #e3e9ef}.vitals{margin-top:1rem;padding:1rem;border-radius:.8rem;background:#f4f9fc}.vitals h4{font-size:.82rem}@media(max-width:767px){.action-strip{align-items:flex-start;flex-direction:column}.action-strip>div:first-child{flex-wrap:wrap}.detail-shell{grid-template-columns:1fr}.detail-shell>nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid #e2e8ee}.detail-shell>nav button{min-width:max-content}.summary-grid,.clinical-grid{grid-template-columns:1fr}.hero-status{display:none}}
</style>
